# v114: „Kik vezették a köztársaságot?” – DPRR (Digital Prosopography of the Roman Republic, King's College London, CC BY-NC 4.0)
import json
D=json.load(open('dprr/data.json'))
C1='#7a4e9c';C2='#c8792b'
OFF={'praetor':('praetor','praetor'),'consul':('consul','consul'),'legatus (lieutenant)':('legatus (alvezér)','legatus (lieutenant)'),'proconsul':('proconsul','proconsul'),
     'tribunus plebis':('néptribunus (tribunus plebis)','tribune of the plebs (tribunus plebis)'),'quaestor':('quaestor','quaestor'),'legatus (ambassador)':('legatus (követ)','legatus (ambassador)'),
     'monetalis':('pénzverő tisztviselő (monetalis)','moneyer (monetalis)'),'triumphator':('triumphator (diadalmenetet tartott)','triumphator (celebrated a triumph)'),'senator - office unknown':('senator, hivatala ismeretlen','senator, office unknown')}
def fy(a,l): return ('Kr. e. %d' if l=='hu' else '%d BC')%(-a)
def nm(s): return s.split(' ',1)[1]
def build(l):
    H=l=='hu';T=lambda h,e:h if H else e
    sw=lambda c:'<span class="sw" style="background:%s"></span>'%c
    th=lambda n:('{:,}'.format(n).replace(',',' ') if n>=10000 else str(n))
    o=[]
    o.append('    <section class="card" id="dprrcard">')
    o.append('      <h2>'+T('Kik vezették a köztársaságot? Tisztségviselők adatbázisa','Who ran the Republic? A database of office-holders')+'</h2>')
    o.append('      <p class="hint">'+T('A <i>Digital Prosopography of the Roman Republic</i> (DPRR) a köztársaság ismert elitjét gyűjti egy adatbázisba: %s személy (közülük %d nő) és %s tisztségviselési adat %d féle hivatalról, Kr. e. 509-től az Actiumi csata évéig (Kr. e. 31), néhány későbbi adattal. Az adatok közel négyötöde Broughton <i>The Magistrates of the Roman Republic</i> című művéből származik. Az alábbi számok saját összesítések az adatbázis nyilvános lekérdezőfelületéről letöltött adatokból.'%(th(D['persons']),D['women'],th(D['posts']),D['offices']),'The <i>Digital Prosopography of the Roman Republic</i> (DPRR) gathers the known elite of the Republic into one database: %s persons (%d of them women) and %s records of office-holding for %d kinds of office, from 509 BC to the year of Actium (31 BC), with a few later records. Almost four fifths of the records come from Broughton’s <i>The Magistrates of the Roman Republic</i>. The figures below are my own aggregates of data downloaded from the database’s public query endpoint.'%('{:,}'.format(D['persons']),D['women'],'{:,}'.format(D['posts']),D['offices']))+'</p>')
    o.append('      <h4 class="aqh4">'+T('A consulság: patríciusok és plebejusok, 50 évenként','The consulship: patricians and plebeians, by 50 years')+'</h4>')
    mx=max(b['n'] for b in D['bins'])
    for b in D['bins']:
        p=b['pat'];q=b['n']-p
        lab=T('%d–%d'%(-b['a'],-b['b']),'%d–%d'%(-b['a'],-b['b']))
        o.append('      <div class="dprow"><span class="dpl">'+lab+'</span><div class="aqtot dpbar" style="width:%.1f%%">'%(78.0*b['n']/mx)+('<div class="aqb" style="width:%.2f%%;background:%s">%d</div>'%(100.0*p/b['n'],C1,p) if p else '')+('<div class="aqb" style="width:%.2f%%;background:%s">%d</div>'%(100.0*q/b['n'],C2,q) if q else '')+'</div></div>')
    o.append('      <p class="hint aqleg">'+sw(C1)+T(' patrícius · ',' patrician · ')+sw(C2)+T(' nem patrícius (az adatbázis nem jelöli patríciusnak). Évszámok Kr. e.; a sáv hossza a consulságok számával arányos, az utolsó sáv csak 29 év (59–31).',' not patrician (not flagged as patrician in the database). Dates BC; bar length is proportional to the number of consulships, the last bar covers only 29 years (59–31).')+'</p>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('DPRR, „consul” hivatalú bejegyzések (%d, közülük %d bizonytalannak jelölt; %d személy), a kezdő év szerint csoportosítva; a pótconsulok (consul suffectus, 69 bejegyzés) nincsenek benne. Saját összesítés.'%(D['cons'],D['consunc'],D['consp']),'DPRR, records with the office “consul” (%d, %d of them flagged uncertain; %d persons), grouped by starting year; suffect consuls (consul suffectus, 69 records) are not included. Own aggregation.'%(D['cons'],D['consunc'],D['consp']))+'</p>')
    o.append('      <p class="hint">'+T('Az első száz évben az adatbázis minden consult patríciusként tart számon. Kr. e. 409 és 360 között csak 23 consulság szerepel, mert ezekben az évtizedekben többnyire consuli hatalmú katonai tribunusok álltak az állam élén (az adatbázisban 285 ilyen bejegyzés van). Az első nem patrícius consul az adatbázisban L. Sextius Lateranus, Kr. e. 366-ban; ettől kezdve a két rend nagyjából fele-fele arányban osztozik, a Kr. e. 2. század közepétől pedig a plebejusok vannak többségben.','For the first hundred years the database records every consul as a patrician. Between 409 and 360 BC only 23 consulships appear, because in those decades the state was mostly headed by military tribunes with consular power (285 such records in the database). The first non-patrician consul in the database is L. Sextius Lateranus in 366 BC; from then on the two orders share the office roughly half and half, and from the mid-2nd century BC the plebeians are in the majority.')+'</p>')
    o.append('      <h4 class="aqh4">'+T('A legtöbb consult adó nemzetségnevek','The family names with most consuls')+'</h4>')
    o.append('      <div class="regwrap"><table class="regtab aniotab dprrtab">')
    o.append('        <thead><tr><th>'+T('Nemzetségnév (nomen)','Family name (nomen)')+'</th><th>'+T('Consulság','Consulships')+'</th><th>'+T('Személy','Persons')+'</th><th>'+T('Jelölés az adatbázisban','Flag in the database')+'</th></tr></thead>')
    o.append('        <tbody>')
    for n,k,dp,allp,anyp in D['nom']:
        o.append('          <tr><td>%s</td><td>%d</td><td>%d</td><td>%s</td></tr>'%(n,k,dp,T('mind patríciusként jelölt','all flagged patrician') if allp else T('vegyes: nem mindegyik consul van patríciusként jelölve','mixed: not every consul is flagged patrician')))
    o.append('        </tbody>')
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('DPRR, saját összesítés a consulok nemzetségneve szerint. Az azonos nevű személyek nem feltétlenül rokonok; a nemzetségnév több, egymástól független családot is jelölhet.','DPRR, own aggregation by the consuls’ nomen. Persons with the same name are not necessarily related; one nomen may cover several unrelated families.')+'</p>')
    r=D['rep']
    o.append('      <p class="hint">'+T('<b>A legtöbbször consul:</b> C. Marius hétszer (Kr. e. 107, 104–100, 86), T. Quinctius Capitolinus Barbatus hatszor (Kr. e. 471–439), utánuk hat személy ötször, köztük C. Iulius Caesar (Kr. e. 59, 48, 46, 45, 44).','<b>Most often consul:</b> C. Marius seven times (107, 104–100, 86 BC), T. Quinctius Capitolinus Barbatus six times (471–439 BC), followed by six persons with five each, among them C. Iulius Caesar (59, 48, 46, 45, 44 BC).')+'</p>')
    nv=D['nov'];nc=sum(1 for x in nv if x[1].startswith('cos'))
    o.append('      <p class="hint">'+T('<b>„Új emberek” (homines novi).</b> Az adatbázis %d személyt jelöl így, vagyis olyanként, akinek a családjából előtte senki nem jutott el a legmagasabb hivatalokig; közülük %d lett consul vagy pótconsul. Köztük van L. Sextius Lateranus (cos. 366), M. Porcius Cato (195), C. Marius (107), M. Tullius Cicero (63) és M. Vipsanius Agrippa (37).'%(len(nv),nc),'<b>“New men” (homines novi).</b> The database flags %d persons as such, i.e. as men from whose family nobody had reached the highest offices before; %d of them became consul or suffect consul. They include L. Sextius Lateranus (cos. 366), M. Porcius Cato (195), C. Marius (107), M. Tullius Cicero (63) and M. Vipsanius Agrippa (37).'%(len(nv),nc))+'</p>')
    o.append('      <h4 class="aqh4">'+T('A tíz leggyakoribb hivatal az adatbázisban','The ten most frequent offices in the database')+'</h4>')
    top=D['top'][:10];m2=top[0][1]
    for k,n in top:
        o.append('      <div class="dprow"><span class="dpl dpl2">'+OFF[k][0 if H else 1]+'</span><div class="aqtot dpbar" style="width:%.1f%%"><div class="aqb" style="width:100%%;background:#5b6f86">%d</div></div></div>'%(58.0*n/m2,n))
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('DPRR, tisztségviselési bejegyzések száma hivatalonként; saját összesítés. A számok az ismert adatokat mutatják, nem azt, hányan viselték valójában a hivatalt: néptribunusból és quaestorból évente több volt, mint consulból, mégis kevesebbet ismerünk név szerint.','DPRR, number of office-holding records per office; own aggregation. The numbers show what is known, not how many actually held the office: there were more tribunes of the plebs and quaestors each year than consuls, yet fewer are known by name.')+'</p>')
    o.append('      <p class="hint">'+T('<b>Mire figyeljünk.</b> A Kr. e. 5–4. századi névsorok jóval későbbi római hagyományon alapulnak, a megbízhatóságuk vitatott; az adatbázis azt rögzíti, amit a források állítanak. A „patrícius” jelölés az adatbázis szerkesztőinek besorolása (800 személynél, 11-nél bizonytalanként). Az adatbázis %d nőt tartalmaz; a hivatalt viselők közül a legtöbben Vesta-szüzek (38 bejegyzés). A projekt weboldalát robotellenőrzés védi, ezért csak a nyilvános lekérdezőfelületet és annak dokumentációját használtam.'%D['women'],'<b>Points to bear in mind.</b> The lists for the 5th–4th centuries BC rest on much later Roman tradition and their reliability is debated; the database records what the sources state. The “patrician” flag is a classification by the database’s editors (800 persons, 11 of them marked uncertain). The database contains %d women; most of those holding an office are Vestal Virgins (38 records). The project website is protected by a bot check, so I used only the public query endpoint and its documentation.'%D['women'])+'</p>')
    o.append('    </section>')
    return '\n'.join(o)+'\n'
SRCLI=lambda l:('      <li><b>A köztársaság tisztségviselői.</b> Digital Prosopography of the Roman Republic (DPRR), King’s College London, romanrepublic.ac.uk; RDF-változat és SPARQL-lekérdezőfelület: John Bradley (CC BY-NC 4.0). Letöltve 2026. november 12-én; a kártya számai saját összesítések.</li>' if l=='hu' else '      <li><b>Office-holders of the Republic.</b> Digital Prosopography of the Roman Republic (DPRR), King’s College London, romanrepublic.ac.uk; RDF version and SPARQL endpoint: John Bradley (CC BY-NC 4.0). Downloaded on 12 November 2026; the figures on the card are own aggregates.</li>')
SUB=('4876 személy és 9807 hivatalviselés: consulok, nemzetségek, „új emberek”','4,876 persons and 9,807 offices held: consuls, families, “new men”')
